def rearange_string(s):
  count = {}
  for char in s:
    if char not in count:
      count[char] = 1
    else:
      count[char] += 1
  sorted_chars = sorted(count.items(), key=lambda x:x[1], reverse=True)
  result = ''
  while len(sorted_chars) > 0:
    first_char, first_count = sorted_chars.pop(0)
    second_char, second_count = sorted_chars.pop(0)
    result += first_char
    result += second_char
    if first_count - 1 > 0:
      sorted_chars.append((first_char, first_count - 1))
    if second_count - 1 > 0:
      sorted_chars.append((second_char, second_count - 1))
  return result

