def amicable_numbers_sum(num):
  def get_divisors(n):
    divisors = []
    for i in range(1, int(math.sqrt(n)) + 1):
      if n % i == 0:
        divisors.append(i)
        if i != n // i:
          divisors.append(n // i)
    return divisors

  def is_amicable(a, b):
    return sum(get_divisors(a)) == b and sum(get_divisors(b)) == a

  total_sum = 0
  for i in range(1, num):
    if is_amicable(i, i+1):
      total_sum += i
  return total_sum

