def magic_square_test(square):
  # Calculate the sum of the first row
  sum_first_row = sum(square[0])

  # Check if all rows have the same sum
  for row in square:
    if sum(row) != sum_first_row:
      return False

  # Check if all columns have the same sum
  for col in range(len(square)):
    column_sum = 0
    for row in square:
      column_sum += row[col]
    if column_sum != sum_first_row:
      return False

  # Check if the diagonals have the same sum
  diagonal_sum1 = 0
  diagonal_sum2 = 0
  for i in range(len(square)):
    diagonal_sum1 += square[i][i]
    diagonal_sum2 += square[i][len(square)-1-i]

  if diagonal_sum1 != sum_first_row or diagonal_sum2 != sum_first_row:
    return False

  # Check if all numbers are unique
  all_numbers = set()
  for row in square:
    for num in row:
      if num not in all_numbers:
        all_numbers.add(num)
      else:
        return False

  return True

